figures.script:
diagram("direction: right
(Power on) as a
[Firmware: BIOS / UEFI] as b #amber
[Bootloader: GRUB] as c #blue
[Kernel loads] as d #violet
[init / systemd] as e #mint
(Login) as f
a -> b
b -> c : POST, find boot device
c -> d : load kernel + initrd
d -> e : mount root, start drivers
e -> f : start services
@0 a -> b
@1 b -> c
@2 c -> d
@3 d -> e
@4 e -> f
loop 6");
